        return std::make_tuple(0, 0, 0);
    }
    int sum = 0;
    int lo = v[0];
    int hi = v[0];
    for (int x : v) {
        sum += x;
        if (x < lo) lo = x;
        if (x > hi) hi = x;
    }
    return std::make_tuple(sum, lo, hi);
}

