#include <vector>

std::vector<std::vector<int>> mul_table(int n) {
    std::vector<std::vector<int>> table;
    for (int i = 0; i < n; ++i) {
        std::vector<int> row;
        for (int j = 0; j < n; ++j) {
            row.push_back((i + 1) * (j + 1));
        }
        table.push_back(row);
    }
    return table;
}

