#include <vector>

int count_greater(const std::vector<int>& v, int threshold) {
    int count = 0;
    for (std::vector<int>::const_iterator it = v.begin(); it != v.end(); ++it) {
        if (*it > threshold) {
            ++count;
        }
    }
    return count;
}

