answer_code:
#include <vector>

struct MinMax {
    int min;
    int max;
};

MinMax min_max(const std::vector<int>& v) {
    if (v.empty()) {
        return MinMax{0, 0};
    }
    int lo = v[0];
    int hi = v[0];
    for (int x : v) {
        if (x < lo) { lo = x; }
        if (x > hi) { hi = x; }
    }
    return MinMax{lo, hi};
}

