#include <utility>
#include <vector>

void order_pair(int& a, int& b) {
    if (a > b) {
        std::swap(a, b);
    }
}

void swap_ends(std::vector<int>& v) {
    if (v.size() >= 2) {
        std::swap(v.front(), v.back());
    }
}

